from Crypto.Util.number import *
from sympy import *

def get_n(a):
    p = getPrime(a)
    q1 = getPrime(a)
    q2 = getPrime(a)
    n1 = p*q1
    n2 = p*q2
    return n1, n2

flag = b'wpst{*******}'

p = getPrime(1024)
q = getPrime(1024)
n = p * q

n1, n2 = get_n(256)
e = 65537
e1 = getPrime(256)
e2 = getPrime(256)
c1 = pow(e1, e, n1)
c2 = pow(e2, e, n2)

m = bytes_to_long(flag)

c3 = pow(m, e1, n)
c4 = pow(m, e2, n)

print(f'n = {n}')
print(f'n1 + n2 = {n1 + n2}')
print(f'n1 * n2 = {n1 * n2}')
print(f'e = {e}')
print(f'e1 = {e1}')
print(f'e2 = {e2}')
print(f'c1 = {c1}')
print(f'c2 = {c2}')
print(f'c3 = {c3}')
print(f'c4 = {c4}')

